#pragma once
#include "engine/free_arc.hpp"
#include "arc_parameter_checks.hpp"
static void freeArcCheck(App& app,const std::string& dir){
    auto require=[](bool ok,const char* reason){if(!ok)throw std::runtime_error(std::string("free arc: ")+reason);};
    auto countGroups=[](const Document& d){size_t n=0;for(const auto& g:d.groups().records())if(g.isAlive()&&g.label=="Joined arrows")++n;return n;};
    auto read=[&](const Session& s,ObjectId id){arrows::ArrowParams p;bool ok=false;require(arrows::readArrow(s.doc,id,&p,&ok).ok()&&ok,"read arrow parameters");return p;};
    auto draw=[&](Session& s,Vec2 begin,Vec2 end,double sag,uint32_t mods=0){
        s.selected.clear();require(s.activateCommand("chooseArrowTool_FreeArc"),"free arc tool registered");std::vector<Vec2> trace;arrows::flattenArc(begin,end,sag,arrows::Tessellation(),&trace);auto before=s.doc.digest();
        require(s.gesture(PointerPhase::Down,begin,mods).ok(),"arc press");require(s.gesture(PointerPhase::Move,end,mods).ok(),"choose endpoint");require(s.gesture(PointerPhase::Up,end,mods).ok(),"fix endpoints");require(s.doc.digest()==before,"endpoints remain preview until bend is chosen");
        auto tool=dynamic_cast<arrows::ArrowTool*>(s.entries[s.activeIndex].tool.get());require(tool&&tool->state().arcStage==2,"second-stage bend preview");auto mid=arrows::arcMidpoint(begin,end,sag);tool->hoverPreview(s,mid,mods);require(s.doc.digest()==before,"bend preview does not mutate document");auto preview=tool->previewParams();
        require(s.gesture(PointerPhase::Down,mid,mods).ok()&&s.gesture(PointerPhase::Up,mid,mods).ok(),"confirm bend");
        ObjectId id=s.doc.arrows().records().back().id;auto stored=read(s,id);require(std::abs(stored.arcSagitta-preview.arcSagitta)<1e-8&&stored.head.atEnd==preview.head.atEnd,"preview and commit agree");return id;
    };
    Session geometry;auto view=geometry.view();view.scale=2;view.dpiScale=1;
    auto arrowCount=[](const Document& d){size_t count=0;for(const auto& a:d.arrows().records())if(a.isAlive())++count;return count;};
    for(double sag:{20.71067811865475,-20.71067811865475,50.,120.71067811865475}){
        Session trial;trial.arrowHeadTier=0;trial.setView(view);auto id=draw(trial,Vec2(0,0),Vec2(100,0),sag,core::kModAlt);auto p=read(trial,id);require(std::abs(p.arcSagitta-sag)<.01,"drag chooses radius, direction, and sweep including major arcs");
        trial.selected={ObjectRef(ObjectKind::Arrow,id)};auto mid=arrows::arcMidpoint(p.begin,p.end,p.arcSagitta);trial.gesture(PointerPhase::Down,mid);trial.gesture(PointerPhase::Move,Vec2(50,-35));trial.gesture(PointerPhase::Up,Vec2(50,-35));require(std::abs(read(trial,id).arcSagitta+35)<1e-6,"middle handle follows pointer");
    }
    Session joined;joined.arrowHeadTier=0;joined.setView(view);auto main=arrows::withHeadTier(arrows::resolvePreset(58,Vec2(0,0),Vec2(140,0),.6),0);main.arcSagitta=50;ObjectId base;require(arrows::addArrow(joined.doc,main,.6,&base).ok(),"base curved arrow");joined.refresh();
    auto hit=arrows::arcJunction(joined.doc,arrows::arcMidpoint(main.begin,main.end,main.arcSagitta),1);require(hit.valid(),"capture curved shaft");
    auto branch=draw(joined,hit.point+Vec2(-85,65),hit.point,25);auto incoming=read(joined,branch);require(!incoming.head.atEnd&&countGroups(joined.doc)==1,"incoming branch loses internal head and merges");
    arrows::ArrowGeometry branchGeometry;arrows::buildArrowGeometry(incoming,.6,arrows::Tessellation(),&branchGeometry);const auto& ink=branchGeometry.shafts.front();auto direction=ink.back()-ink[ink.size()-2];direction=direction*(1/length(direction));require(dot(direction,hit.tangent)>.995,"incoming branch has tangent continuity");
    require(joined.undo().ok()&&arrowCount(joined.doc)==1&&countGroups(joined.doc)==0,"joining is one undo step");require(joined.undo(true).ok()&&countGroups(joined.doc)==1,"redo restores joined arrows");
    auto start=arrows::arcJunction(joined.doc,Vec2(115,35),20);require(start.valid(),"outgoing branch start");auto out=draw(joined,start.point,start.point+Vec2(65,65),-18);require(read(joined,out).head.atEnd&&!read(joined,out).head.atBegin,"outgoing branch keeps its external head");require(countGroups(joined.doc)==1,"multiple branches merge into one group");
    auto digest=joined.doc.digest();joined.selected.clear();joined.activateCommand("chooseArrowTool_FreeArc");joined.gesture(PointerPhase::Down,Vec2(-100,-50));joined.gesture(PointerPhase::Move,Vec2(-30,-80));joined.cancel();require(joined.doc.digest()==digest,"Escape/cancel leaves no object");
    require(arrowCount(joined.doc)==3,"adding another branch preserves all existing members");
    require(joined.save(dir+"/joined-curves.r62doc",false).ok()&&joined.save(dir+"/joined-curves.cdxml",true).ok(),"save joined curves");Session native,xml;require(native.open(dir+"/joined-curves.r62doc").ok()&&xml.open(dir+"/joined-curves.cdxml").ok(),"reopen joined curves");require(countGroups(native.doc)==1&&countGroups(xml.doc)==1&&arrowCount(xml.doc)==3,"grouping and branch geometry survive both formats");
    Session straight;straight.arrowHeadTier=0;straight.setView(view);auto line=arrows::withHeadTier(arrows::resolvePreset(0,Vec2(0,0),Vec2(180,0),.6),0);ObjectId lineId;arrows::addArrow(straight.doc,line,.6,&lineId);straight.refresh();auto incomingLine=draw(straight,Vec2(70,-70),Vec2(120,0),-15);require(!read(straight,incomingLine).head.atEnd&&countGroups(straight.doc)==1,"capture straight shaft");
    size_t groupsBefore=countGroups(straight.doc);auto loose=draw(straight,Vec2(140,-90),Vec2(150,1),22,core::kModAlt);require(read(straight,loose).head.atEnd&&countGroups(straight.doc)==groupsBefore,"Alt disables joining");straight.save(dir+"/joined-straight.cdxml",true);
    auto& sized=app.s;sized.doc=Document();sized.history.clear();sized.selected.clear();sized.input.bindDocument(sized.doc.id());std::vector<ObjectId> ordinary;ObjectId mechanism,fishhook;std::string mechanismBefore,fishhookBefore;
    int row=0;for(uint32_t preset:{0u,10u,38u,13u,40u,58u,49u,57u}){auto p=arrows::resolvePreset(preset,Vec2(0,row*35),Vec2(130,row*35),.6);if(preset==49||preset==57){p.mechanism=true;p.head.length=3.2;p.head.width=2.24;}ObjectId id;require(arrows::addArrow(sized.doc,p,.6,&id).ok(),"size fixture");if(preset==49){mechanism=id;mechanismBefore=arrows::encodeArrowParams(p);}else if(preset==57){fishhook=id;fishhookBefore=arrows::encodeArrowParams(p);}else ordinary.push_back(id);++row;}sized.refresh();
    const double lengths[]={3.2,6,9,13.5,18};for(int tier=0;tier<5;++tier){app.setArrowHeadTier(tier,false);for(auto id:ordinary){auto p=read(sized,id);require(std::abs(p.head.length-lengths[tier])<1e-8&&p.begin.x==0&&p.end.x==130,"global size applies to all ordinary styles without changing arrow length");}require(arrows::encodeArrowParams(read(sized,mechanism))==mechanismBefore&&arrows::encodeArrowParams(read(sized,fishhook))==fishhookBefore,"mechanism and fishhook are unchanged");}
    app.setArrowHeadTier(0,false);sized.save(dir+"/uniform-small-arrows.cdxml",true);
    {auto& scene=app.s;scene.doc=Document();scene.history.clear();scene.selected.clear();scene.input.bindDocument(scene.doc.id());scene.arcBendLocked=false;scene.setView(view);
     auto source=arrows::resolvePreset(58,Vec2(0,0),Vec2(100,0),.6);source.arcSagitta=-50;auto target=arrows::resolvePreset(58,Vec2(0,200),Vec2(200,200),.6);target.arcSagitta=15;ObjectId a,b;arrows::addArrow(scene.doc,source,.6,&a);arrows::addArrow(scene.doc,target,.6,&b);scene.refresh();
     auto circleBefore=arc_properties::read(target);app.arcCurvatureAction(a,40,false);app.arcCurvatureAction(b,41,false);auto circleAfter=arc_properties::read(read(scene,b));require(std::abs(circleAfter.sweep-arc_properties::read(source).sweep)<1e-8&&length(circleBefore.center-circleAfter.center)<1e-8&&std::abs(circleBefore.radius-circleAfter.radius)<1e-8,"paste angle keeps target centre and radius");require(scene.undo().ok()&&read(scene,b).arcSagitta==15,"paste is undoable");
     auto before=scene.doc.digest();app.arcCurvatureAction(a,42,false);require(scene.arcBendLocked&&scene.doc.digest()==before,"locking preserves existing drawing");
     scene.selected.clear();scene.activateCommand("chooseArrowTool_FreeArc");scene.gesture(PointerPhase::Down,Vec2(0,400));scene.gesture(PointerPhase::Up,Vec2(160,400));auto locked=scene.doc.arrows().records().back().id;require(std::abs(read(scene,locked).arcSagitta+80)<1e-8,"locked bend applies to new arcs");
     scene.selected={ObjectRef(ObjectKind::Arrow,locked)};auto middle=arrows::arcMidpoint(read(scene,locked).begin,read(scene,locked).end,read(scene,locked).arcSagitta);scene.gesture(PointerPhase::Down,middle);scene.gesture(PointerPhase::Move,middle+Vec2(0,40));scene.gesture(PointerPhase::Up,middle+Vec2(0,40));require(std::abs(read(scene,locked).arcSagitta+40)<1e-8,"middle drag freely overrides preset bend lock");
     HMENU menu=CreatePopupMenu();app.appendArcContextMenu(menu,a);require(GetMenuState(menu,41,MF_BYCOMMAND)==UINT(-1)&&GetMenuState(menu,43,MF_BYCOMMAND)!=UINT(-1),"unavailable paste hidden while locked");for(int i=0;i<GetMenuItemCount(menu);++i){auto state=GetMenuState(menu,i,MF_BYPOSITION);if(!(state&MF_SEPARATOR))require(!(state&(MF_DISABLED|MF_GRAYED)),"arc context has no disabled entries");}DestroyMenu(menu);
     app.arcCurvatureAction(a,43,false);require(!scene.arcBendLocked,"unlock restores free bend");
     auto major=arrows::resolvePreset(58,Vec2(0,800),Vec2(100,800),.6);major.arcSagitta=120.71067811865475;
     auto wide=arrows::resolvePreset(0,Vec2(0,950),Vec2(120,950),.6);ObjectId majorId,wideId;
     require(arrows::addArrow(scene.doc,major,.6,&majorId).ok()&&arrows::addArrow(scene.doc,wide,.6,&wideId).ok(),"curvature fixtures");scene.refresh();
     app.arcCurvatureAction(majorId,44,false);app.arcCurvatureAction(wideId,45,false);
     require(std::abs(read(scene,wideId).arcSagitta-108.12725198639417)<.001,"copy curvature retains major sweep on straight arrow");
     app.arcCurvatureAction(majorId,46,false);require(scene.arcCurvatureLocked&&scene.arcCurvatureMajor,"major curvature lock");
     app.arcCurvatureAction(majorId,47,false);require(!scene.arcCurvatureLocked,"curvature unlock");
     scene.selected={ObjectRef(ObjectKind::Arrow,wideId)};scene.activateCommand("chooseSelectionTool_Marquee");auto straight=arrows::resolvePreset(0,Vec2(0,1100),Vec2(120,1100),.6);ObjectId straightId;require(arrows::addArrow(scene.doc,straight,.6,&straightId).ok(),"straight fixture");scene.refresh();
     scene.selected={ObjectRef(ObjectKind::Arrow,straightId)};scene.gesture(PointerPhase::Down,Vec2(60,1100));scene.gesture(PointerPhase::Move,Vec2(60,1070));scene.gesture(PointerPhase::Up,Vec2(60,1070));require(std::abs(read(scene,straightId).arcSagitta)>1.,"straight arrow middle drag creates curvature");
     scene.selected.clear();scene.activateCommand("chooseArrowTool_FreeArc");scene.gesture(PointerPhase::Down,Vec2(0,600));scene.gesture(PointerPhase::Up,Vec2(0,600));auto tool=dynamic_cast<arrows::ArrowTool*>(scene.entries[scene.activeIndex].tool.get());require(tool->state().arcStage==1,"first click selects start");tool->hoverPreview(scene,Vec2(120,600),core::kModAlt);scene.gesture(PointerPhase::Down,Vec2(120,600),core::kModAlt);scene.gesture(PointerPhase::Up,Vec2(120,600),core::kModAlt);require(tool->state().arcStage==2,"second click selects end");auto digest=scene.doc.digest();scene.cancel();require(scene.doc.digest()==digest,"cancel after endpoint selection is clean");
    }
    Session centering;for(int tier=0;tier<5;++tier)for(double bow:{-120.710678,20.710678,50.,120.710678}){
        auto p=arrows::withHeadTier(arrows::resolvePreset(58,Vec2(0,0),Vec2(100,0),.6),tier);p.arcSagitta=bow;arrows::ArrowGeometry g;require(arrows::buildArrowGeometry(p,.6,arrows::Tessellation(),&g).ok()&&!g.heads.empty(),"head geometry");const auto& head=g.heads.front();require(head.outline.size()==4&&length(head.outline[2]-g.shafts.front().back())<1e-6,"recess joins curved shaft without a gap");
        if(tier==3&&bow<0){p.begin=Vec2(0,0);p.end=Vec2(100,0);ObjectId id;arrows::addArrow(centering.doc,p,.6,&id);}
    }centering.save(dir+"/centered-arc-head.cdxml",true);
    std::ofstream(dir+"/arc-workflow-checks.json")<<"{\"two_stage\":true,\"click_endpoints\":true,\"copy_paste_angle\":true,\"paste_undo\":true,\"lock_new_and_edited_only\":true,\"unlock\":true,\"hidden_disabled_actions\":true,\"triangle_centred\":true}";
    std::ofstream(dir+"/arc-checks.json")<<"{\"free_drag\":true,\"radius_sweep_direction\":true,\"major_arcs\":true,\"middle_handle\":true,\"preview_commit\":true,\"curved_capture\":true,\"straight_capture\":true,\"smooth_junction\":true,\"incoming_outgoing_branches\":true,\"group_move_ready\":true,\"undo_redo\":true,\"cancel\":true,\"alt_disables_capture\":true,\"native_cdxml_groups\":true,\"head_tiers\":5,\"mechanism_excluded\":true}";
    arrowSizePreviewCheck(app,dir);
    checkArcParameterPastes(app,dir);
}
